/// typing replaces it, and Return renames; right-click ▸ Paste works too; Esc cancels the
/// dialog and renames nothing.
#[test]
fn the_rename_keyword_field_selects_pastes_and_cancels() {
    let mut h = demo([1200.0, 800.0]);
